module morse_counter #(\n    parameter MAX_LEN = 32,\n    parameter MOD = 1000000007\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire bit_in,\n    output reg [31:0] answer,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n\n    // Internal registers\n    reg [MAX_LEN-1:0] s;\n    reg [5:0] len;\n    reg [31:0] sm;\n    reg [1:0] state;\n    reg [31:0] sum_f_new_reg;\n\n    // Combinational block to compute sum_f_new_reg\n    always @(*) begin\n        integer i, j;\n        reg [31:0] f_comb [0:MAX_LEN];\n        reg [31:0] sum4;\n        reg [MAX_LEN-1:0] rev_s;\n        reg [5:0] z [0:MAX_LEN];\n        integer l, r;\n        reg [5:0] max_z;\n        reg [5:0] new;\n        reg [31:0] sum_f_new_temp;\n        reg bad;\n        \n        // Initialize f_comb\n        for (i = 0; i <= MAX_LEN; i = i + 1) begin\n            f_comb[i] = 32'd0;\n        end\n        sum_f_new_temp = 32'd0;\n        \n        if (len > 0) begin\n            // DP\n            f_comb[len] = 32'd1;\n            sum4 = 32'd1;\n            for (j = len-1; j >= 0; j = j - 1) begin\n                bad = 1'b0;\n                if (j + 4 <= len) begin\n                    if ((s[j] == 1'b0 && s[j+1] == 1'b0 && s[j+2] == 1'b1 && s[j+3] == 1'b1) ||\n                        (s[j] == 1'b0 && s[j+1] == 1'b1 && s[j+2] == 1'b0 && s[j+3] == 1'b1) ||\n                        (s[j] == 1'b1 && s[j+1] == 1'b1 && s[j+2] == 1'b1 && s[j+3] == 1'b0) ||\n                        (s[j] == 1'b1 && s[j+1] == 1'b1 && s[j+2] == 1'b1 && s[j+3] == 1'b1))\n                        bad = 1'b1;\n                end\n                if (bad) begin\n                    f_comb[j] = (sum4 - f_comb[j+4]) % MOD;\n                end else begin\n                    f_comb[j] = sum4;\n                end\n                sum4 = (sum4 + f_comb[j]) % MOD;\n            end\n            \n            // Reverse string\n            for (i = 0; i < len; i = i + 1) begin\n                rev_s[i] = s[len-1-i];\n            end\n            \n            // Z-function\n            l = 0;\n            r = 0;\n            for (i = 1; i < len; i = i + 1) begin\n                if (i <= r) begin\n                    if (r - i + 1 < z[i - l]) begin\n                        z[i] = r - i + 1;\n                    end else begin\n                        z[i] = z[i - l];\n                    end\n                end else begin\n                    z[i] = 0;\n                end\n                while (i + z[i] < len && rev_s[z[i]] == rev_s[i + z[i]]) begin\n                    z[i] = z[i] + 1;\n                end\n                if (i + z[i] - 1 > r) begin\n                    l = i;\n                    r = i + z[i] - 1;\n                end\n            end\n            \n            // Max z\n            max_z = 0;\n            for (i = 1; i < len; i = i + 1) begin\n                if (z[i] > max_z) max_z = z[i];\n            end\n            \n            new = len - max_z;\n            \n            // Sum f[0:new-1]\n            sum_f_new_temp = 32'd0;\n            for (i = 0; i < new; i = i + 1) begin\n                sum_f_new_temp = (sum_f_new_temp + f_comb[i]) % MOD;\n            end\n        end\n        sum_f_new_reg = sum_f_new_temp;\n    end\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            len <= 6'd0;\n            s <= {MAX_LEN{1'b0}};\n            sm <= 32'd0;\n            done <= 1'b0;\n            state <= IDLE;\n        end else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start && len < MAX_LEN) begin\n                        s[len] <= bit_in;\n                        len <= len + 6'd1;\n                        state <= COMPUTE;\n                    end\n                end\n                COMPUTE: begin\n                    sm <= (sm + sum_f_new_reg) % MOD;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Output\n    always @(posedge clk) begin\n        answer <= sm;\n    end\n\nendmodule